  const { clue, line } = instance
  if (!puzzle.getCellsAreFilled([clue, ...line])) return true
  const w = windowLength(instance, puzzle)
  const c = puzzle.getValue(clue)
  for (let i = 0; i < w; i++) if (puzzle.getValue(line[i]) === c) return true
  return false
}

